INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'ASEAN $10,000 Early Acceptance Scholarship', 'This early acceptance scholarship is awarded to talented international students from the ASEAN region who intend to pursue a coursework degree at Macquarie University, offsetting approximately 25% of their annual tuition fees. Among one of the most g', 'AUD $10000/year', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/asean-10-000-early-acceptance-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ASEAN $10,000 Early Acceptance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'ASEAN Partner Institution Scholarship', 'To recognise the strong relationship between Macquarie University and institutions in the ASEAN region, this ASEAN Partner Scholarship is awarded to prospective students from the region with a quest for knowledge. The scholarship amount is valued up ', 'AUD $15000/year', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/asean-partner-institution-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ASEAN Partner Institution Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Bangladesh $10,000 Early Acceptance Scholarship', 'This scholarship offers talented international students from Bangladesh AUD $10,000 per year towards their studies at Macquarie University. The scholarship is available for the full duration of an eligible Bachelor\'s and Master\'s coursework degree. F', 'AUD $10000/year — Applicants will be assessed automatically for this scholarship. Successful candidates will receive the scholarship with their Course Letter of Offer.', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/bangladesh-10-000-early-acceptance-scholarship/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bangladesh $10,000 Early Acceptance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'English Language Scholarship for Sponsored Students', 'The English Language Scholarship is awarded to students who wish to study an undergraduate or postgraduate course and improve their English.', '100% of English Language Program tuition fees for up to 10 weeks', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/english-language-scholarship-for-sponsored-students/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'English Language Scholarship for Sponsored Students') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Faculty of Science and Engineering Women in STEM Scholarship', 'Recognising excellence in Science, Information Technology and Engineering, this scholarship is to fund female-identifying scholars based on excellence and equity, to encourage and support female-identifying scholars to undertake a career in STEM.', 'Up to AUD $5000', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/faculty-of-science-and-engineering-women-in-stem-scholarship/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Faculty of Science and Engineering Women in STEM Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'India $10,000 Early Acceptance Scholarship', 'This scholarship is awarded to eligible students from India who are commencing a coursework degree at Macquarie University.', 'See scholarship details', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/india-10-000-early-acceptance-scholarship/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'India $10,000 Early Acceptance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Macquarie Advantage Humanitarian Scholarship', 'The Macquarie Advantage Humanitarian Scholarship provides full tuition fee support for students from refugee and asylum‑seeking backgrounds to undertake undergraduate study at Macquarie University.This scholarship is awarded for the full duration of ', '100% of total tuition fees', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/macquarie-advantage-humanitarian-scholarship/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Macquarie Advantage Humanitarian Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Macquarie University $10,000 Early Acceptance Scholarship', 'This scholarship offers talented international students from eligible countries AUD $10,000 per year towards their studies at Macquarie University. The scholarship is applied throughout the duration of an eligible Bachelor\'s and Master\'s coursework d', 'AUD $10000/year', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/macquarie-university-10-000-early-acceptance-scholarship/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Macquarie University $10,000 Early Acceptance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Macquarie University $15,000 Early Acceptance Scholarship', 'This scholarship offers talented international students from Vietnam, Indonesia and the Philippines AUD $15,000 per year towards their studies at Macquarie University. Valued among the most generous scholarships in Australia, the scholarship is avail', 'AUD $10000/year — This scholarship is valid for the full duration of the course.', 'https://search.studyaustralia.gov.au/scholarship/macquarie-university-15000-early-acceptance-scholarship/800c6d9acf476a957b674e99c456bcd6', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Macquarie University $15,000 Early Acceptance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Macquarie University $5,000 Regional Scholarship', 'This scholarship is awarded to all eligible students who are commencing a coursework degree at Macquarie University.', 'Up to AUD $5000', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/macquarie-university-5-000-regional-scholarship/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Macquarie University $5,000 Regional Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Macquarie University Alumni Scholarship', 'This scholarship is awarded to all eligible Macquarie University alumni international students for postgraduate studies.', '10% of total tuition fees', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/macquarie-university-alumni-scholarship/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Macquarie University Alumni Scholarship') LIMIT 1;
