INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'FUNED - RMIT Scholarship', 'If you are an international student from Mexico applying for a Masters by Coursework program at RMIT University, you may be eligible for this jointly funded scholarship by RMIT and the Mexican Foundation for Education, Technology and Science (FUNED).', 'Up to AUD $12000 — RMIT UP Academic English Bursary for Latin American students if you are required to study ELICOS; tuition fee support by RMIT to the value of 25% of the tuition fees for Masters by Coursework program for a maximum of two years.', 'https://www.rmit.edu.au/scholarships/international-scholarships/funed-rmit-scholarship#overview', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'FUNED - RMIT Scholarship') LIMIT 1;
