INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'A smart CPR feedback device for cardiac arrest (PhD scholarship)', 'This PhD project focuses on developing the first-ever closed-loop cardiopulmonary resuscitation (CPR) feedback device. The device uses non-invasive sensors to measure blood oxygenation in the brain and tells the CPR provider how to adjust their compr', 'AUD $33637/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/a-smart-cpr-feedback-device-for-cardiac-arrest-phd-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'A smart CPR feedback device for cardiac arrest (PhD scholarship)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Australia Awards Scholarship', 'As an Australia Awards student you need to attend a five-week Introductory Academic Program (IAP). It’s a chance for you to get help with enrolment, learning skills, language expectations and our technology and teaching systems. You will receive prog', 'See scholarship details', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/australia-awards-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Australian South Sea Islander Community Foundation Scholarship', 'The Australian South Sea Islander Community Foundation was established by the Queensland Government in 2001 as a perpetual fund to provide scholarships to Australian South Sea Islander undergraduate students.', 'You will receive an Australian South Sea Islander Community Foundation Scholarship. The value and number of scholarships will vary annually depending on funding. These scholarships are subject to annual funding.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/australian-south-sea-islander-community-foundation-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian South Sea Islander Community Foundation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Bachelor of Arts Impact Scholarship', 'The Bachelor of Arts Impact Scholarship is awarded to high-achieving school leavers and eligible gap year students starting our Bachelor of Arts degree. This scholarship is targeted at high achievers to enable their continued success at QUT through f', 'Up to AUD $15000', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/bachelor-of-arts-impact-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bachelor of Arts Impact Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'China Scholarship Council Scholarship', 'A scholarship for future research students studying in any faculty.', 'a tuition fee waiver for the duration of your course, which is normally 1.5 years for masters students and 3 years for doctoral students.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/china-scholarship-council', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'China Scholarship Council Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Clayton Adam Florence Wilson Award for Biomechanics and Spine Research', 'The Clayton Adam Florence Wilson Award is available to promote spine research at QUT, and honours the stellar contribution to scientific innovation in spine research made by our former Research Director, Professor Clayton Adam. Clayton joined QUT in ', 'See scholarship details', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/CAFW-Award', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Clayton Adam Florence Wilson Award for Biomechanics and Spine Research') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Data61 PhD Scholarship', 'At CSIRO\'s Data61, we aim to develop top-quality doctoral students who will prosper in careers in Australia’s data-skilled workforce. Our PhD scholarship program provides opportunities for outstanding postgraduate students with demonstrated academic ', 'a full scholarship which includes a base stipend at the Australian Government Research Training (RTP) Program base rate supplemented with a top-up scholarship of $10,000 per annum. Data61 PhD scholarships have a maximum term of 3 years and 6 months.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/data61-phd-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Data61 PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Dynamic soft matter materials PhD scholarship', 'As the successful applicant you will complete your PhD in the field of organic photochemistry for advanced reprogrammable material design.Based in our Science and Engineering Faculty, you will also spend time at our research hub at the Karlsruhe Inst', 'a minimum of $30,000 per year, for 3 yearsa QUT tuition fee sponsorship (for international students).', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/dynamic-soft-matter-materials-phd-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dynamic soft matter materials PhD scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Equity Work Integrated Learning (WIL) Bursaries', 'If you\'re completing a work integrated learning (WIL) placement and experiencing financial hardship, you may be eligible for a bursary of up to $750.', 'Up to AUD $1000 — bursary of $300, $500, $750 or $1000 based on your demonstrated need.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/equity-work-integrated-learning-wil-bursaries', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Equity Work Integrated Learning (WIL) Bursaries') LIMIT 1;
