INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Investigation on Bubble Dynamics Under Electric Fields in Water Electrolysis Process', 'We are seeking a PhD candidate to investigate gas bubble dynamics under the influence of electric fields, with a particular focus on applications in electrochemical hydrogen production. The project will examine the physical mechanisms governing bubbl', 'AUD $37010/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/investigation-on-bubble-dynamics-under-electric-fields-in-water-electrolysis-process', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Investigation on Bubble Dynamics Under Electric Fields in Water Electrolysis Process') LIMIT 1;
