INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'QUT College Merit Scholarship', 'This scholarship is sponsored by QUT College. It is available to international students who have demonstrated academic achievement or can demonstrate how they intend to commit to success in their future studies.', 'A scholarship to cover 25% of the tuition fees for the first semester of your Diploma or Foundation program at QUT International College. An invitation to a Pathway Scholarship ceremony, certificate of recognition, and access to extra-curricular prof', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-international-college-pathway-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT College Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'QUT Excellence Scholarship (Academic)', 'The QUT Excellence Scholarship is our premier offering for high achievers. We award more than 130 scholarships annually, worth more than $3.5 million.In addition to the financial support, the program helps you to make the most of your QUT experience ', 'Up to AUD $30000 — scholarships valued at $30,000 each for study in any discipline, scholarships valued at $30,000 each for courses in the Faculty of Science and Faculty of Engineering only.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/excellence-scholarship-academic', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT Excellence Scholarship (Academic)') LIMIT 1;
