INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'QUT-CSIRO PhD Scholarship in Deep Learning for Hyperspectral Image Classification', 'Hyperspectral imaging is one of the rapidly growing domains in remote sensing primarily due to the breadth of applications on a variety of areas, from plant disease detection to object tracking. For example, hyperspectral imaging provides an opportun', 'A scholarship between $37,000 and $40,000 per year for 3 years (consisting of a base stipend of $27,000 and a top-up between $10,000 and $13,000) with a possible extension of 6 months. Up to $5,000 per year for project costs (to be agreed between CSI', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-csiro-phd-scholarship-in-deep-learning-for-hyperspectral-image-classification', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT-CSIRO PhD Scholarship in Deep Learning for Hyperspectral Image Classification') LIMIT 1;
