INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Shaping the future of mobility in rural and remote regions (PhD scholarship)', 'Headquartered at the Queensland University of Technology (QUT), AVR3 is a pioneering research hub dedicated to advancing automated vehicle (AV) technologies specifically tailored for the unique challenges of rural, regional, and remote Australian roa', 'AUD $41555/year — You\'ll receive a stipend of $41,555 per annum for a maximum duration of 3.5 years while undertaking a QUT PhD (1.75 years for MPhil). The duration includes an extension of up to 6 months (PhD) or 3 months (MPhil) if approved for you', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/shaping-the-future-of-mobility-in-rural-and-remote-regions-phd-scholarship', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Shaping the future of mobility in rural and remote regions (PhD scholarship)') LIMIT 1;
