INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Academic and Music Excellence Scholarships', NULL, 'Scholarships are awarded following the results of the ACER Scholarship test sat in February in the year of eligibility. There are no set quotas. Scholarships are awarded dependent upon merit.', 'https://search.studyaustralia.gov.au/scholarship/academic-and-music-excellence-scholarships/6024e1cdd3dceb0c861363e96d4380ac', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00902F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic and Music Excellence Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'China Scholarship Council Research Scholarships', 'The China Scholarship Council Research Scholarship is a collaborative arrangement that provides support to candidates from the People\'s Republic of China to undertake a PhD at Western Sydney University. We encourage applications from candidates in al', '"Western Sydney University will provide a tuition fee waiver for successful applicants for a maximum period of up to 48 months.\r\n"', 'https://www.westernsydney.edu.au/schools/grs/scholarships/china_scholarship_council_research_scholarships', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00917K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'China Scholarship Council Research Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Research Scholarships', 'Western Sydney University supports higher degree research candidates with a range of scholarship opportunities. Research scholarships are released periodically, and each type of scholarship has specific application dates, eligibility criteria and con', 'Up to AUD $105564', 'https://www.westernsydney.edu.au/schools/grs/scholarships/main_round_scholarships', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00917K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Alphacrucis Higher Degree Scholarship', 'This scholarship provides financial support, in the form of a fee subsidy, to students undertaking HDR research at AC. This is a merit-based scholarship for students with a demonstrated record of academic excellence.', 'See scholarship details', 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00958A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alphacrucis Higher Degree Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Financial assistance scholarships', 'Enrolled HDR students facing financial difficulties may be eligible for a financial assistance scholarship, in the form of a fee subsidy. Students can apply at any time during their enrolment, typically for up to 2 semesters of financial support.', 'See scholarship details', 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00958A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Financial assistance scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'HDR Travel Grant', 'This grant is available to assist HDR candidates with travel costs (up to $1500) associated with research-related activities that will enhance their thesis.', 'See scholarship details', 'https://www.ac.edu.au/research/hdr/funding-opportunities/', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00958A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'HDR Travel Grant') LIMIT 1;
