INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'International Master of Physiotherapy Scholarship', 'The University of Notre Dame Australia (University) offers the International Master of Physiotherapy Scholarship to provide tuition assistance to international students enrolling in the Master of Physiotherapy program at the University of Notre Dame ', 'The value of the Scholarship is $7,500 fee reduction of annual indicative tuition fees for the full duration of the \r\nprogram.', 'https://www.notredame.edu.au/__data/assets/pdf_file/0037/437698/International-Master-of-Physiotherapy-Scholarship-Conditions.pdf', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Master of Physiotherapy Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Notre Dame Australia International Business and Commerce Scholarship', 'The University of Notre Dame Australia (University) offers the International Business and Commerce scholarship to provide tuition assistance to international students enrolling in Undergraduate Business and Commerce programs at the University of Notr', 'The value of the Scholarship is $10,000 fee reduction of annual indicative tuition fees for the full duration of the program.', 'https://www.notredame.edu.au/__data/assets/pdf_file/0032/339944/NDA-International-Business-and-Commerce-Undergraduate-Scholarship-T-and-Cs.pdf', '2026-11-05 12:33:23', '2026-11-05 12:33:23' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Notre Dame Australia International Business and Commerce Scholarship') LIMIT 1;
